define <vscale x 2 x double> @test_insert_with_index_nxv2f64(<vscale x 2 x double> %a, double %d, i64 %idx) {
  %res = insertelement <vscale x 2 x double> %a, double %d, i64 %idx
  ret <vscale x 2 x double> %res
}

